SELECT eo.execution_source, eo.decision_code, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losses, SUM(p.realized_pnl>0) AS wins, ROUND(SUM(p.realized_pnl),4) AS pnl_usdt, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_ret_pct FROM crypto_ai.paper_position p JOIN crypto_ai.execution_opportunity eo ON eo.latest_signal_id=p.signal_id AND eo.status='EXECUTED' WHERE p.status='CLOSED' AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY eo.execution_source, eo.decision_code ORDER BY n DESC LIMIT 40;
SELECT CASE WHEN s.risk_reward_ratio IS NULL THEN 'NULL' WHEN s.risk_reward_ratio < 0.5 THEN '<0.5' WHEN s.risk_reward_ratio < 1 THEN '0.5-1' WHEN s.risk_reward_ratio < 2 THEN '1-2' ELSE '>=2' END AS rr_bucket, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losses, SUM(p.realized_pnl>0) AS wins, ROUND(SUM(p.realized_pnl),4) AS pnl_usdt FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id=p.signal_id WHERE p.status='CLOSED' AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY rr_bucket ORDER BY rr_bucket LIMIT 10;